final GeoFirePoint center = GeoFirePoint(const GeoPoint(35.681236, 139.767125));
final Stream<List<DocumentSnapshot<Map<String, dynamic>>>> stream = GeoCollectionReference<Map<String, dynamic>>(FirebaseFirestore.instance.collection('locations')).subscribeWithin(
  center: center,
  radiusInKm: 50,
  field: 'geo',
  geopointFrom: (data) => (data['geo'] as Map<String, dynamic>)['geopoint'] as GeoPoint,
);
